import{_ as e,o as r,c as n,a2 as d}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Flow Steps","description":"All triggers, actions, and helpers of a Flow at a glance.","frontmatter":{"title":"Flow Steps","description":"All triggers, actions, and helpers of a Flow at a glance."},"headers":[],"relativePath":"en/referenz/flow-schritte.md","filePath":"en/referenz/flow-schritte.md","lastUpdated":1787319236000}'),a={name:"en/referenz/flow-schritte.md"};function o(s,t,i,l,h,g){return r(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="flow-steps-—-reference" tabindex="-1">Flow Steps — Reference <a class="header-anchor" href="#flow-steps-—-reference" aria-label="Permalink to &quot;Flow Steps — Reference&quot;">​</a></h1><p>All the steps the Flow editor offers, in the order of its three tabs.</p><p><strong>Pro</strong> marks steps that are only available on the highest plan.</p><hr><h2 id="triggers" tabindex="-1">Triggers <a class="header-anchor" href="#triggers" aria-label="Permalink to &quot;Triggers&quot;">​</a></h2><p>A Flow has exactly one. → <a href="/en/flows/trigger">Trigger</a></p><table tabindex="0"><thead><tr><th>Trigger</th><th>Description in the interface</th><th>Configuration</th></tr></thead><tbody><tr><td><strong>New entry</strong></td><td><em>A new entry was added</em></td><td>Grid</td></tr><tr><td><strong>Entry was changed</strong></td><td><em>An existing entry was changed</em></td><td>Grid, optional field condition</td></tr><tr><td><strong>Entry via form</strong></td><td><em>New entry added via form</em></td><td>Grid and Form</td></tr><tr><td><strong>Entry changed via form</strong></td><td><em>Existing entry changed via form</em></td><td>Grid and Form</td></tr><tr><td><strong>Webhook</strong></td><td><em>Triggered by an external request</em></td><td>–</td></tr><tr><td><strong>Show page</strong></td><td><em>Start the Flow and load a page</em></td><td>Page</td></tr></tbody></table><hr><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="working-with-your-own-data" tabindex="-1">Working with your own data <a class="header-anchor" href="#working-with-your-own-data" aria-label="Permalink to &quot;Working with your own data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th><th style="text-align:center;">Pro</th></tr></thead><tbody><tr><td><strong>Create entry</strong></td><td><em>Creates a new entry</em></td><td style="text-align:center;">–</td></tr><tr><td><strong>Update entry</strong></td><td><em>Update an entry with new values</em></td><td style="text-align:center;">–</td></tr><tr><td><strong>Load all entries</strong></td><td><em>Load all entries of a Grid</em></td><td style="text-align:center;">–</td></tr></tbody></table><h3 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th><th style="text-align:center;">Pro</th><th>Settings</th></tr></thead><tbody><tr><td><strong>E-Mail</strong></td><td><em>Send an e-mail</em></td><td style="text-align:center;">–</td><td>To, Subject, Content, Sender name, Reply to, Files, Use HTML in content</td></tr><tr><td><strong>HTTP request</strong></td><td><em>Send any HTTP request</em></td><td style="text-align:center;">–</td><td>URL, Method, Content Type, Query, Headers, Content, Username, Password</td></tr><tr><td><strong>Slack</strong></td><td>Send message</td><td style="text-align:center;">–</td><td>Message, <strong>Webhook URL</strong> ⁽¹⁾</td></tr><tr><td><strong>MS Teams Message</strong></td><td>Send message</td><td style="text-align:center;">–</td><td>Message, <strong>Webhook URL</strong> ⁽¹⁾</td></tr><tr><td><strong>Firebase Cloud Messaging</strong></td><td>Send message</td><td style="text-align:center;">–</td><td>Topic or device tokens, Title, Content, <strong>API key</strong> ⁽¹⁾</td></tr><tr><td><strong>Hubspot</strong></td><td>Create contact</td><td style="text-align:center;">–</td><td><strong>API token</strong> ⁽¹⁾, Contact data</td></tr><tr><td><strong>Magenta Business SMS</strong></td><td>Send SMS</td><td style="text-align:center;"><strong>yes</strong></td><td><strong>API key and secret</strong> ⁽¹⁾, Sender, Recipient, Text</td></tr><tr><td><strong>Magenta Business Verify</strong></td><td>Send confirmation code via SMS</td><td style="text-align:center;"><strong>yes</strong></td><td><strong>Credentials</strong> ⁽¹⁾</td></tr><tr><td><strong>Magenta Business Verify Check</strong></td><td>Check code</td><td style="text-align:center;"><strong>yes</strong></td><td><strong>Credentials</strong> ⁽¹⁾</td></tr></tbody></table><p>⁽¹⁾ Requires your <strong>own account</strong> with the respective provider. → <a href="/en/integrationen/ueberblick">Integrations overview</a></p><h3 id="files-and-content" tabindex="-1">Files and content <a class="header-anchor" href="#files-and-content" aria-label="Permalink to &quot;Files and content&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th><th style="text-align:center;">Pro</th><th>Settings</th></tr></thead><tbody><tr><td><strong>QR Code</strong></td><td><em>Creates a QR code</em></td><td style="text-align:center;">–</td><td></td></tr><tr><td><strong>PDF to text</strong></td><td><em>Convert a PDF to text</em></td><td style="text-align:center;"><strong>yes</strong></td><td>PDF file URL, extract text per page</td></tr><tr><td><strong>URL to PDF</strong></td><td><em>Convert a web page to PDF</em></td><td style="text-align:center;"><strong>yes</strong></td><td>Web page URL</td></tr><tr><td><strong>Import CSV file</strong></td><td><em>Imports a CSV file</em></td><td style="text-align:center;">–</td><td>Link to CSV file, column separator, first row contains column names, encoding, skip empty rows, trim whitespace</td></tr><tr><td><strong>Speech to text</strong></td><td><em>Convert audio to text</em></td><td style="text-align:center;"><strong>yes</strong></td><td></td></tr><tr><td><strong>Document Analyzer</strong></td><td>Evaluate documents with AI</td><td style="text-align:center;"><strong>yes</strong></td><td></td></tr><tr><td><strong>Calendar Event</strong></td><td>Create a calendar entry</td><td style="text-align:center;">–</td><td>Title, description, times</td></tr><tr><td><strong>DATEV Lohn &amp; Gehalt</strong></td><td><em>Creates a DATEV import file</em></td><td style="text-align:center;"><strong>yes</strong></td><td>Entry, <strong>access key and password</strong> ⁽¹⁾</td></tr></tbody></table><h3 id="ai-and-code" tabindex="-1">AI and code <a class="header-anchor" href="#ai-and-code" aria-label="Permalink to &quot;AI and code&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th><th style="text-align:center;">Pro</th><th>Settings</th></tr></thead><tbody><tr><td><strong>OpenAI</strong></td><td>ChatGPT</td><td style="text-align:center;"><strong>yes</strong></td><td>Prompt, additional instructions — <strong>no own account needed</strong></td></tr><tr><td><strong>JavaScript</strong></td><td><em>Runs JavaScript code</em></td><td style="text-align:center;">– ⁽²⁾</td><td>JavaScript code, generate with AI</td></tr></tbody></table><p>⁽²⁾ The step itself is available on every plan. Only <strong>Generate with AI</strong> is plan-restricted — writing your own code always works.</p><h3 id="interacting-with-people" tabindex="-1">Interacting with people <a class="header-anchor" href="#interacting-with-people" aria-label="Permalink to &quot;Interacting with people&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th><th style="text-align:center;">Pro</th></tr></thead><tbody><tr><td><strong>Show page</strong></td><td><em>Shows a page for user interaction</em></td><td style="text-align:center;">–</td></tr><tr><td><strong>Create link to page</strong></td><td><em>Creates a link to a page in the Flow</em></td><td style="text-align:center;">–</td></tr><tr><td><strong>Pre-filled form link</strong></td><td><em>Updates an entry</em></td><td style="text-align:center;">–</td></tr></tbody></table><p>→ <a href="/en/flows/aktionen">Actions</a> · <a href="/en/flows/seiten-in-flows">Pages in Flows</a></p><hr><h2 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Helper</th><th>Description</th><th>Settings</th></tr></thead><tbody><tr><td><strong>Router</strong></td><td><em>Take different paths</em></td><td>Condition per output</td></tr><tr><td><strong>Parallel</strong></td><td><em>Runs the following steps separately for each list item.</em></td><td>–</td></tr><tr><td><strong>Merge runs</strong></td><td><em>Waits for all list runs to complete and then continues the Flow.</em></td><td>–</td></tr><tr><td><strong>Wait</strong></td><td><em>Pauses the Flow for a set duration.</em></td><td>Seconds to wait</td></tr></tbody></table><p>→ <a href="/en/flows/router-und-parallel">Router and Parallel</a></p><h3 id="operators-in-the-router" tabindex="-1">Operators in the Router <a class="header-anchor" href="#operators-in-the-router" aria-label="Permalink to &quot;Operators in the Router&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><em>equals</em></td><td><em>does not equal</em></td></tr><tr><td><em>is greater than</em></td><td><em>is less than</em></td></tr><tr><td><em>is greater than or equal to</em></td><td><em>is less than or equal to</em></td></tr><tr><td><em>begins with</em></td><td><em>ends with</em></td></tr><tr><td><em>contains</em></td><td></td></tr><tr><td><em>is before</em></td><td><em>is after</em></td></tr><tr><td><em>is empty</em></td><td><em>is not empty</em></td></tr><tr><td><em>is true</em></td><td><em>is false</em></td></tr></tbody></table><p>Combine with <strong>and</strong> or <strong>or</strong>.</p><hr><h2 id="not-offered" tabindex="-1">Not offered <a class="header-anchor" href="#not-offered" aria-label="Permalink to &quot;Not offered&quot;">​</a></h2><p>These elements exist internally but do not appear in the editor and are not part of the product:</p><table tabindex="0"><thead><tr><th>Element</th><th>Note</th></tr></thead><tbody><tr><td><strong>End</strong></td><td>No separate step needed</td></tr><tr><td><strong>Exclusive Gateway</strong></td><td>Not in the step selection area</td></tr><tr><td><strong>Load all entries</strong> (view variant)</td><td>Deprecated; the Grid variant is current</td></tr></tbody></table><p>Older Flows may still contain deprecated <strong>triggers</strong>, marked as such in the editor. They keep working but should be replaced when you revise the Flow.</p><hr><h2 id="what-doesn-t-exist" tabindex="-1">What doesn&#39;t exist <a class="header-anchor" href="#what-doesn-t-exist" aria-label="Permalink to &quot;What doesn&#39;t exist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Expected</th><th>Instead</th></tr></thead><tbody><tr><td>Scheduled start</td><td>An external system calls the <a href="/en/flows/webhook-trigger">webhook URL</a></td></tr><tr><td>Trigger for deleted entries</td><td>Set a status field instead of deleting</td></tr><tr><td>Merging <strong>Router</strong> branches</td><td>Run each branch to completion on its own. <em>Merge runs</em> only closes <strong>Parallel</strong> sections.</td></tr><tr><td>Triggering by calculated fields</td><td>React to the underlying field instead</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/was-ist-ein-flow">What is a Flow</a></li><li><a href="/en/flows/trigger">Trigger</a></li><li><a href="/en/flows/aktionen">Actions</a></li></ul>',39)])])}const p=e(a,[["render",o]]);export{m as __pageData,p as default};
